window.docContents[12].resolve({"/Fermat___s-Last-Theorem-for-exponent-37/Supporting-machinery-developed-in-the-project/#Kummer___s-Criterion-and-Regular-Primes-in-Lean--Fermat___s-Last-Theorem-for-exponent-37--Supporting-machinery-developed-in-the-project--Reflection-___-Spiegelungssatz":{"contents":"The weak reflection principle on the unit side: divisibility of the plus class\nnumber  implies a non-trivial -eigencomponent in the minus\nclass group for some reflection-component index . This is the project's bridge\nfrom unit-side data to class-side data, used as one input to the Lehmer–Vandiver\ndescent.\n\nConditional on the weak reflection principle,  is equivalent to \ndividing a Bernoulli numerator in the Kummer range — an alternative form of Kummer's\ncriterion routed through the reflection / Spiegelungssatz machinery rather than the\nSinnott / circular-unit route.\n\n","context":"Kummer's Criterion and Regular Primes in Lean\u0009Fermat's Last Theorem for exponent 37\u0009Supporting machinery developed in the project","header":"11.6.3. Reflection / Spiegelungssatz","id":"/Fermat___s-Last-Theorem-for-exponent-37/Supporting-machinery-developed-in-the-project/#Kummer___s-Criterion-and-Regular-Primes-in-Lean--Fermat___s-Last-Theorem-for-exponent-37--Supporting-machinery-developed-in-the-project--Reflection-___-Spiegelungssatz"}});